    return text.replaceAllMapped(_githubPrRegExp, (match) {
      final owner = match.group(1)!;
      final repo = match.group(2)!;
      final number = match.group(3)!;
      return '${match.group(0)!} [github-pr:$owner/$repo#$number]';
    });
  }

